// @@PRE mode_ColorClouds




/** Softly floating colorful clouds.
 * This is a very smooth effect that moves colorful clouds randomly around the LED strip.
 * It was initially intended for rather unobtrusive ambient lights (with very slow speed settings).
 * Nevertheless, it appears completely different and quite vibrant when the sliders are moved near
 * to their limits. No matter in which direction or in which combination...
 * Ported to WLED from https://github.com/JoaDick/EyeCandy/blob/master/ColorClouds.h
 */

// @@PRE mode_perlinmove




// WLED-SR effects

/////////////////////////
//     Perlin Move     //
/////////////////////////
// 16 bit perlinmove. Use Perlin Noise instead of sinewaves for movement. By Andrew Tuline.
// Controls are speed, # of pixels, faderate.

// @@FX mode_perlinmove
void mode_perlinmove(void) {
  if (SEGLEN <= 1) FX_FALLBACK_STATIC;
  SEGMENT.fade_out(255-SEGMENT.custom1);
  for (int i = 0; i < SEGMENT.intensity/16 + 1; i++) {
    unsigned locn = perlin16(strip.now*128/(260-SEGMENT.speed)+i*15000, strip.now*128/(260-SEGMENT.speed)); // Get a new pixel location from moving noise.
    unsigned pixloc = map(locn, 50*256, 192*256, 0, SEGLEN-1);                                            // Map that to the length of the strand, and ensure we don't go over.
    SEGMENT.setPixelColor(pixloc, SEGMENT.color_from_palette(pixloc%255, false, PALETTE_SOLID_WRAP, 0));
  }
}
// @@PRE mode_wavesins
 // mode_perlinmove()



/////////////////////////
//     Waveins         //
/////////////////////////
// Uses beatsin8() + phase shifting. By: Andrew Tuline

// @@FX mode_wavesins
void mode_wavesins(void) {

  for (unsigned i = 0; i < SEGLEN; i++) {
    uint8_t bri = sin8_t(strip.now/4 + i * SEGMENT.intensity);
    uint8_t index = beatsin8_t(SEGMENT.speed, SEGMENT.custom1, SEGMENT.custom1+SEGMENT.custom2, 0, i * (SEGMENT.custom3<<3)); // custom3 is reduced resolution slider
    //SEGMENT.setPixelColor(i, ColorFromPalette(SEGPALETTE, index, bri, LINEARBLEND));
    SEGMENT.setPixelColor(i, SEGMENT.color_from_palette(index, false, PALETTE_SOLID_WRAP, 0, bri));
  }
}
